    for (Texture62* tex = g_pTextureList; tex; tex = tex->GetNext())
    {
        if (IsKindOf62(&g_kSourceTextureRTTI, tex))
        {
            Texture62* cand = tex;
            if (cand->GetSize() && (g_bDumpMenuTextures || !HasMenusPath(cand)))
            {
                int slot = -1;
                int i = 0;
                do
                {
                    if (slot != -1) break;
                    if (!textures[i])
                        slot = i;
                    i++;
                } while (i < 200);
                if (slot != -1)
                {
                    for (int j = 199; j > slot; j--)
                        textures[j] = textures[j - 1];
                    textures[slot] = cand;
                }
            }
        }
    }
    File62* file = new File62("textures.txt", 1, 0x1000, true);
    if (!file || !file->Open(false, false))
    {
        DebugLog62("The file textures.txt could not be opened.");
        return;
    }
    int totalKb = 0;
    char buffer[1024];
    sprintf_s(buffer, 1024,
        "Texture dump for cell: %s grid: (%d, %d) worldspace: %s \n---------------------------------------\n",
        g_TES62->GetCurrentCell() ? g_TES62->GetCurrentCell()->GetFullName() : "{unknown}",
        g_TES62->GetGridX(), g_TES62->GetGridY(),
        g_TES62->GetCurrentCell()
            ? (g_TES62->GetCurrentCell()->GetParentWorldSpace()
                   ? g_TES62->GetCurrentCell()->GetParentWorldSpace()->GetFullName()
                   : "{unknown}")
            : "{unknown}");
    file->Write(buffer, strlen(buffer));
    for (int k = 0; k < 200 && textures[k]; k++)
    {
        textures[k]->GetPath();
        file->Write(buffer, strlen(buffer));
    }
    sprintf_s(buffer, 1024, "---------------------------------------\nTotal memory: %dkb", totalKb);
    file->Write(buffer, strlen(buffer));
    file->Close();
